const bound = new CountQueuingStrategy({ highWaterMark: 256 });  // the capacity
const writer = new WritableStream(sink, bound).getWriter();
for await (const msg of source) {
    if (writer.desiredSize !== null && writer.desiredSize <= 0) {
        dropped++; continue;               // full: shed deliberately, never silently
    }
    await writer.ready;                    // otherwise gate on the sink (back-pressure)
    await writer.write(msg);
}
